<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>云裳女装 · 首页</title>
<style>
  :root{
    --ink:#2b2622; --ink-soft:#6f665e; --cream:#faf6f1; --paper:#ffffff;
    --blush:#efd9d2; --rose:#b76e63; --rose-deep:#9a5449; --gold:#c9a06a;
    --sage:#a8b5a0; --line:#e8e0d8;
  }
  *{margin:0;padding:0;box-sizing:border-box;}
  body{font-family:"PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;background:var(--cream);color:var(--ink);line-height:1.7;}
  a{text-decoration:none;color:inherit;}
  img{max-width:100%;}
  .wrap{max-width:1180px;margin:0 auto;padding:0 24px;}

  /* 顶部导航 */
  header{position:sticky;top:0;z-index:50;background:rgba(250,246,241,.92);backdrop-filter:blur(8px);border-bottom:1px solid var(--line);}
  .nav{display:flex;align-items:center;justify-content:space-between;height:72px;}
  .logo{display:flex;align-items:center;gap:10px;font-size:24px;font-weight:700;letter-spacing:6px;}
  .logo svg{width:34px;height:34px;}
  .nav-links{display:flex;gap:36px;font-size:15px;}
  .nav-links a{padding:6px 2px;border-bottom:2px solid transparent;transition:.25s;}
  .nav-links a:hover,.nav-links a.on{color:var(--rose);border-bottom-color:var(--rose);}
  .nav-icons{display:flex;gap:18px;align-items:center;}
  .nav-icons svg{width:22px;height:22px;stroke:var(--ink);fill:none;stroke-width:1.6;cursor:pointer;transition:.25s;}
  .nav-icons svg:hover{stroke:var(--rose);}

  /* 首屏 */
  .hero{display:grid;grid-template-columns:1.05fr 1fr;gap:48px;align-items:center;padding:72px 0 64px;}
  .hero-tag{display:inline-block;font-size:13px;letter-spacing:4px;color:var(--rose);border:1px solid var(--rose);border-radius:999px;padding:6px 18px;margin-bottom:24px;}
  .hero h1{font-size:52px;line-height:1.25;font-weight:700;letter-spacing:2px;margin-bottom:20px;}
  .hero h1 em{font-style:normal;color:var(--rose);}
  .hero p{color:var(--ink-soft);font-size:16px;max-width:460px;margin-bottom:36px;}
  .btn{display:inline-block;padding:14px 36px;border-radius:999px;font-size:15px;letter-spacing:2px;transition:.25s;border:1px solid var(--ink);}
  .btn-dark{background:var(--ink);color:#fff;}
  .btn-dark:hover{background:var(--rose);border-color:var(--rose);}
  .btn-ghost{background:transparent;color:var(--ink);margin-left:14px;}
  .btn-ghost:hover{color:var(--rose);border-color:var(--rose);}
  .hero-art{background:linear-gradient(160deg,#f3e2da,#e7d3c8);border-radius:180px 180px 24px 24px;padding:40px 24px 0;display:flex;justify-content:center;box-shadow:0 24px 60px rgba(183,110,99,.18);}
  .hero-art svg{width:100%;max-width:380px;height:auto;display:block;}

  /* 通用标题 */
  .sec-head{text-align:center;margin:88px 0 44px;}
  .sec-head small{display:block;font-size:13px;letter-spacing:6px;color:var(--rose);margin-bottom:10px;}
  .sec-head h2{font-size:32px;letter-spacing:4px;font-weight:700;}
  .sec-head .flourish{margin-top:14px;display:flex;justify-content:center;}

  /* 分类 */
  .cats{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;}
  .cat{background:var(--paper);border:1px solid var(--line);border-radius:20px;padding:34px 20px 28px;text-align:center;transition:.3s;cursor:pointer;}
  .cat:hover{transform:translateY(-8px);box-shadow:0 18px 40px rgba(43,38,34,.10);border-color:var(--blush);}
  .cat svg{width:72px;height:72px;margin-bottom:16px;}
  .cat h3{font-size:18px;letter-spacing:3px;margin-bottom:6px;}
  .cat span{font-size:13px;color:var(--ink-soft);}

  /* 商品卡片 */
  .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;}
  .card{background:var(--paper);border-radius:18px;overflow:hidden;border:1px solid var(--line);transition:.3s;}
  .card:hover{transform:translateY(-6px);box-shadow:0 20px 44px rgba(43,38,34,.12);}
  .card .art{display:block;}
  .card .art svg{width:100%;height:auto;display:block;}
  .card .info{padding:18px 20px 22px;}
  .card .info h4{font-size:16px;font-weight:600;letter-spacing:1px;margin-bottom:6px;}
  .card .info .meta{display:flex;justify-content:space-between;align-items:center;}
  .price{color:var(--rose-deep);font-size:18px;font-weight:700;}
  .price small{font-size:12px;font-weight:400;margin-right:2px;}
  .tag-new{font-size:11px;color:#fff;background:var(--rose);border-radius:999px;padding:3px 10px;letter-spacing:1px;}
  .more-row{text-align:center;margin-top:44px;}

  /* 品牌理念 */
  .motto{margin-top:96px;background:linear-gradient(120deg,#3a332e,#54463c);color:#f5ede6;border-radius:28px;padding:64px 56px;display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center;}
  .motto h2{font-size:30px;letter-spacing:4px;margin-bottom:18px;}
  .motto p{color:#d8ccc2;font-size:15px;margin-bottom:28px;}
  .motto .btn{border-color:#e9d9c8;color:#f5ede6;}
  .motto .btn:hover{background:var(--rose);border-color:var(--rose);}
  .motto svg{width:100%;height:auto;}

  /* 服务保障 */
  .perks{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:80px;}
  .perk{display:flex;gap:16px;align-items:flex-start;background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:26px;}
  .perk svg{width:40px;height:40px;flex:none;stroke:var(--rose);fill:none;stroke-width:1.6;}
  .perk h4{font-size:16px;letter-spacing:2px;margin-bottom:4px;}
  .perk p{font-size:13px;color:var(--ink-soft);}

  /* 页脚 */
  footer{margin-top:100px;background:#2b2622;color:#cfc6bd;}
  .foot-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1.4fr;gap:40px;padding:64px 0 44px;}
  .foot-grid h5{color:#f3ece4;font-size:16px;letter-spacing:3px;margin-bottom:18px;}
  .foot-grid a,.foot-grid p{display:block;font-size:13.5px;margin-bottom:10px;color:#cfc6bd;}
  .foot-grid a:hover{color:var(--gold);}
  .foot-brand{font-size:22px;letter-spacing:6px;color:#f3ece4;margin-bottom:14px;font-weight:700;}
  .foot-bottom{border-top:1px solid #443d36;padding:20px 0;font-size:12px;text-align:center;color:#9b9188;}

  @media(max-width:960px){
    .hero{grid-template-columns:1fr;padding-top:48px;}
    .hero h1{font-size:38px;}
    .cats,.grid{grid-template-columns:repeat(2,1fr);}
    .motto{grid-template-columns:1fr;padding:44px 32px;}
    .perks{grid-template-columns:1fr;}
    .foot-grid{grid-template-columns:1fr 1fr;}
    .nav-links{display:none;}
  }
</style>
</head>
